<?php
namespace Tests\Feature;
use App\Models\{Booking,Customer,SadyaPackage,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class CateringApiTest extends TestCase { use RefreshDatabase;
 protected function setUp():void{parent::setUp();$this->seed();}
 public function test_admin_can_login_and_view_dashboard():void{$r=$this->postJson('/api/login',['email'=>'admin@sadyacatering.test','password'=>'password'])->assertOk()->assertJsonStructure(['token','user']);$this->withToken($r['token'])->getJson('/api/dashboard')->assertOk()->assertJsonStructure(['stats'=>['revenue','received','outstanding','expenses','profit'],'series','statuses']);}
 public function test_booking_totals_and_menu_snapshot_are_calculated():void{$u=User::first();$c=Customer::first();$p=SadyaPackage::with('items')->first();$r=$this->actingAs($u)->postJson('/api/bookings',['customer_id'=>$c->id,'sadya_package_id'=>$p->id,'function_type'=>'Wedding','function_date'=>now()->addDay()->toDateString(),'venue'=>'Test Hall','guest_count'=>500,'price_per_leaf'=>150,'additional_charges'=>5000,'discount'=>2500,'advance_amount'=>10000,'status'=>'Confirmed'])->assertCreated();$this->assertEquals(75000,$r['base_amount']);$this->assertEquals(77500,$r['final_amount']);$this->assertEquals(10000,$r['paid_amount']);$this->assertEquals(67500,$r['balance_amount']);$this->assertNotEmpty($r['menu_items']);}
 public function test_customer_detail_includes_booking_history_and_totals():void{$customer=Customer::first();$response=$this->actingAs(User::first())->getJson('/api/customers/'.$customer->id)->assertOk()->assertJsonStructure(['bookings','total_business_value','pending_payments']);$this->assertNotEmpty($response['bookings']);}
 public function test_recording_payment_updates_booking_balance():void{$booking=Booking::with('payments')->first();$before=$booking->final_amount-$booking->payments->sum('amount');$this->actingAs(User::first())->postJson('/api/payments',['booking_id'=>$booking->id,'payment_date'=>now()->toDateString(),'amount'=>5000,'payment_mode'=>'UPI','payment_type'=>'Part Payment'])->assertCreated();$detail=$this->actingAs(User::first())->getJson('/api/bookings/'.$booking->id)->assertOk();$this->assertEquals($before-5000,$detail['balance_amount']);$this->assertCount(2,$detail['payments']);}
 public function test_payment_cannot_exceed_booking_balance():void{$booking=Booking::with('payments')->first();$balance=$booking->final_amount-$booking->payments->sum('amount');$this->actingAs(User::first())->postJson('/api/payments',['booking_id'=>$booking->id,'payment_date'=>now()->toDateString(),'amount'=>$balance+1,'payment_mode'=>'Cash','payment_type'=>'Final Payment'])->assertUnprocessable()->assertJsonValidationErrors('amount');}
 public function test_purchase_payment_uses_quantity_rate_total_and_is_filterable():void{$supplier=\App\Models\Supplier::first();$response=$this->actingAs(User::first())->postJson('/api/purchases',['date'=>now()->toDateString(),'expense_type'=>'Purchase','supplier_id'=>$supplier->id,'description'=>'Coconut purchase','item_name'=>'Coconut','quantity'=>25,'unit'=>'Number','rate'=>40,'amount'=>1,'payment_method'=>'Cash'])->assertCreated();$this->assertEquals(1000,$response['amount']);$this->assertEquals(0,$response['paid_amount']);$this->assertEquals(1000,$response['balance_amount']);$this->actingAs(User::first())->getJson('/api/expenses?expense_type=Purchase&search=Coconut')->assertOk()->assertJsonFragment(['item_name'=>'Coconut','amount'=>1000]);}
 public function test_expense_supports_multiple_partial_payments():void{$expense=$this->actingAs(User::first())->postJson('/api/expenses',['date'=>now()->toDateString(),'expense_type'=>'Labour','paid_to'=>'Test Worker','description'=>'Service balance','amount'=>10000,'initial_payment'=>2500,'payment_method'=>'UPI'])->assertCreated();$this->assertEquals(2500,$expense['paid_amount']);$this->assertEquals(7500,$expense['balance_amount']);$this->actingAs(User::first())->postJson('/api/expenses/'.$expense['id'].'/payments',['payment_date'=>now()->toDateString(),'amount'=>3000,'payment_method'=>'Cash'])->assertCreated();$detail=$this->actingAs(User::first())->getJson('/api/expenses/'.$expense['id'])->assertOk();$this->assertEquals(5500,$detail['paid_amount']);$this->assertEquals(4500,$detail['balance_amount']);$this->assertCount(2,$detail['payments']);}
 public function test_purchase_bill_can_contain_multiple_expense_heads_and_start_unpaid():void{$supplier=\App\Models\Supplier::first();$expense=$this->actingAs(User::first())->postJson('/api/purchases',['date'=>now()->toDateString(),'expense_type'=>'Purchase','supplier_id'=>$supplier->id,'description'=>'Function purchases','invoice_number'=>'BILL-31800','amount'=>0,'items'=>[['item_name'=>'Grocery','amount'=>23000],['item_name'=>'Vegetables','amount'=>3400],['item_name'=>'Pathram','amount'=>5400]]])->assertCreated();$detail=$this->actingAs(User::first())->getJson('/api/expenses/'.$expense['id'])->assertOk();$this->assertEquals(31800,$detail['amount']);$this->assertEquals(0,$detail['paid_amount']);$this->assertEquals(31800,$detail['balance_amount']);$this->assertCount(3,$detail['items']);}
 public function test_new_supplier_and_purchase_type_are_reusable_without_duplicates():void{$user=User::first();$supplier=$this->actingAs($user)->postJson('/api/suppliers',['name'=>' Fresh Market ','mobile'=>'9999999999'])->assertCreated();$duplicate=$this->actingAs($user)->postJson('/api/suppliers',['name'=>'fresh market'])->assertOk();$this->assertEquals($supplier['id'],$duplicate['id']);$type=$this->actingAs($user)->postJson('/api/purchase-types',['name'=>'Banana Leaves'])->assertCreated();$duplicateType=$this->actingAs($user)->postJson('/api/purchase-types',['name'=>' banana leaves '])->assertOk();$this->assertEquals($type['id'],$duplicateType['id']);}
}
